-- Prog 63: ocultar ligas prueba + actualizar a últimos datos oficiales
-- Fuente: TercerTiempo_web/public/programas/63/resultados.html
-- Primera A: J-38 (5 en cancha + 4 defaults + 1 pendiente) + tabla oficial J-38 + cuartos definidos
-- Especial: torneo nuevo J-5 (8 jugados + 1 pendiente), nuevos equipos Galaxi y Juárez FC

-- 0. Ocultar ligas de prueba
update public.leagues set is_public = false, status = 'inactive', updated_at = now()
where slug in ('liga-municipal-perote', 'liga-qa-codex');

-- 1. Especial: cerrar torneo anterior, abrir torneo actual J-5
update public.seasons set status = 'completed'
where id in (select s.id from public.seasons s join public.leagues l on l.id=s.league_id where l.slug='primera-fuerza-especial' and s.slug='temporada-2026');

values ((select id from public.leagues where slug='primera-fuerza-especial'), 'Torneo Actual 2026 · J-5', 'torneo-actual-2026', '2026-09-01', '2026-12-31', 'active')
on conflict (league_id, slug) do update set name=excluded.name, status='active';

-- 1b. Nuevos equipos Especial (Galaxi, Juárez FC)
on conflict (league_id, slug) do update set name=excluded.name, status='active';

-- 1c. Partidos Especial J-5 (torneo-actual-2026)
delete from public.matches
where season_id = (select s.id from public.seasons s join public.leagues l on l.id=s.league_id where l.slug='primera-fuerza-especial' and s.slug='torneo-actual-2026')
  and round_name = 'Jornada 5';


-- 2. Primera A J-38 (misma temporada-2026): resultados en cancha
delete from public.matches
where season_id = (select s.id from public.seasons s join public.leagues l on l.id=s.league_id where l.slug='primera-a' and s.slug='temporada-2026')
  and round_name like 'Jornada 38%';


-- 2b. Cuartos Primera A definidos (horarios pendientes -> scheduled)
delete from public.matches
where season_id = (select s.id from public.seasons s join public.leagues l on l.id=s.league_id where l.slug='primera-a' and s.slug='temporada-2026')
  and stage = 'quarter_finals';


-- 3. Standings oficiales Primera A J-38 (upsert post-trigger)
on conflict (season_id, team_id) do update set
  played=excluded.played, won=excluded.won, drawn=excluded.drawn, lost=excluded.lost,
  goals_for=excluded.goals_for, goals_against=excluded.goals_against,
  goal_difference=excluded.goal_difference, points=excluded.points, updated_at=now();

-- 4. Actualizar descripción ligas a estado Prog63
update public.leagues set description='Liga Luis Pirata Fuente · Torneo Actual 2026 · Jornada 5 (Prog 63)', updated_at=now() where slug='primera-fuerza-especial';
update public.leagues set description='Temporada 2026 · Tabla oficial J-38 + Cuartos definidos (Prog 63)', updated_at=now() where slug='primera-a';
